package org.sleepwell.app;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.provider.AlarmClock;import android.widget.LinearLayout;import java.util.concurrent.*;
/** Standard public entry; all routing uses new explicit internal intents and requires ordinary Save. */
public final class AlarmRequestActivity extends Activity {
 private final ExecutorService reader=Executors.newSingleThreadExecutor();private int generation;private boolean resumed,show,pending,opening;private Alarm draft;private String failure="";
 @Override public void onCreate(Bundle saved){super.onCreate(saved);if(saved!=null&&saved.getBoolean("pending")){try{show=saved.getBoolean("show");if(!show)draft=Alarm.read(new org.json.JSONObject(saved.getString("draft")));pending=true;render();return;}catch(Exception invalid){failure="The interrupted alarm draft could not be restored. Open Alarms to start again.";render();return;}}route(getIntent());}
 @Override protected void onNewIntent(Intent input){super.onNewIntent(input);setIntent(input);route(input);}
 private void route(Intent input){int request=++generation;show=false;pending=false;draft=null;opening=false;failure="";try{if(input!=null&&AlarmClock.ACTION_SHOW_ALARMS.equals(input.getAction())){AlarmRequestInput.show(input);show=true;pending=true;render();openIfVisible();return;}AlarmRequest parsed=AlarmRequestInput.read(input);render();Records.Factory factory=Records.factory;reader.execute(()->{try(Store store=factory.open(getApplicationContext())){Alarm value=parsed.draft(HomeLaunch.draft(getApplicationContext(),store));runOnUiThread(()->{if(isDestroyed()||isFinishing()||request!=generation)return;draft=value;pending=true;render();openIfVisible();});}catch(RuntimeException unavailable){runOnUiThread(()->{if(isDestroyed()||isFinishing()||request!=generation)return;failure="The alarm draft could not be opened. Existing alarms were not changed.";render();});}});}catch(RuntimeException invalid){failure="This alarm request is unsupported or invalid. Use hours 0–23, minutes 0–59, valid Calendar weekdays, a message up to 80 characters and boolean options. Custom ringtone requests must be chosen inside SleepWell.";render();}}
 private void render(){if(isDestroyed())return;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Alarm request",this::finish);Design.space(body,16);if(!failure.isEmpty()){Design.text(body,failure,15,400,Design.MUTED);Design.button(body,"Open alarms",true,this::openAlarms);}else{Design.text(body,show?"Opening Alarms…":pending?"Ready to review your new alarm":"Opening your alarm draft…",20,600,Design.INK);Design.space(body,10);Design.text(body,"Review the time, days and behavior, then tap Save alarm. Requests to skip the UI are ignored. No new alarm is saved or scheduled by this entry screen.",14,400,Design.MUTED);}Design.button(RecordUi.footer(body),"Cancel",false,this::finish);}
 private void openIfVisible(){if(opening||!pending||!resumed||!hasWindowFocus()||isDestroyed()||isFinishing())return;opening=true;pending=false;generation++;try{Intent target=show?new Intent(this,MainActivity.class).putExtra("destination",1):new Intent(this,AlarmEditorActivity.class).putExtra("alarm",draft.json().toString());startActivity(target);finish();}catch(RuntimeException unavailable){opening=false;failure="The requested screen could not be opened. Existing alarms were not changed.";render();}}
 private void openAlarms(){if(!resumed||!hasWindowFocus()||isFinishing())return;generation++;pending=false;try{startActivity(new Intent(this,MainActivity.class).putExtra("destination",1));finish();}catch(RuntimeException unavailable){failure="Alarms could not be opened. Close this screen and open SleepWell again.";render();}}
 @Override protected void onResume(){super.onResume();resumed=true;openIfVisible();}
 @Override protected void onPause(){resumed=false;super.onPause();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused){RecordUi.lightBars(this);openIfVisible();}}
 @Override public void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putBoolean("pending",pending);saved.putBoolean("show",show);if(pending&&draft!=null)saved.putString("draft",draft.json().toString());}
 @Override protected void onDestroy(){generation++;reader.shutdown();super.onDestroy();}
 boolean awaitReaders(long millis)throws InterruptedException{return reader.awaitTermination(millis,TimeUnit.MILLISECONDS);}
}
